Here is the commit message:
net/mlx5e: Fix "scheduling while atomic" in IPsec MAC address
 query

Fix a "scheduling while atomic" bug in mlx5e_ipsec_init_macs() by
replacing mlx5_query_mac_address() with ether_addr_copy() to get the
local MAC address directly from netdev->dev_addr.

The issue occurs because mlx5_query_mac_address() queries the hardware
which involves mlx5_cmd_exec() that can sleep, but it is called from
the mlx5e_ipsec_handle_event workqueue which runs in atomic context.

The MAC address is already available in netdev->dev_addr, so no need
to query hardware. This avoids the sleeping call and resolves the bug.

Call trace:
  BUG: scheduling while atomic: kworker/u112:2/69344/0x00000200
  __schedule+0x7ab/0xa20
  schedule+0x1c/0xb0
  schedule_timeout+0x6e/0xf0
  __wait_for_common+0x91/0x1b0
  cmd_exec+0xa85/0xff0 [mlx5_core]
  mlx5_cmd_exec+0x1f/0x50 [mlx5_core]
  mlx5_query_nic_vport_mac_address+0x7b/0xd0 [mlx5_core]
  mlx5_query_mac_address+0x19/0x30 [mlx5_core]
  mlx5e_ipsec_init_macs+0xc1/0x720 [mlx5_core]
  mlx5e_ipsec_build_accel_xfrm_attrs+0x422/0x670 [mlx5_core]
  mlx5e_ipsec_handle_event+0x2b9/0x460 [mlx5_core]
  process_one_work+0x178/0x2e0
  worker_thread+0x2ea/0x430

Fixes: cee137a63431 ("net/mlx5e: Handle ESN update events")
Signed-off-by: Jianbo Liu <jianbol@nvidia.com>
Reviewed-by: Leon Romanovsky <leonro@nvidia.com>
Signed-off-by: Tariq Toukan <tariqt@nvidia.com>
Reviewed-by: Simon Horman <horms@kernel.org>
Link: https://patch.msgid.link/20260224114652.1787431-6-tariqt@nvidia.com
Signed-off-by: Jakub Kicinski <kuba@kernel.org>

Here is the root cause:
The function `mlx5e_ipsec_init_macs()` calls `mlx5_query_mac_address()`, which performs a hardware command that can sleep. However, this function is invoked from the workqueue `mlx5e_ipsec_handle_event`, which runs in atomic context. This causes a "scheduling while atomic" kernel bug. The MAC address is already stored in `netdev->dev_addr`, so the hardware query is unnecessary and can be replaced with a simple `ether_addr_copy` to avoid the sleeping call.

Here is the patch:

 static void mlx5e_ipsec_init_macs(struct mlx5e_ipsec_sa_entry *sa_entry,
 				  struct mlx5_accel_esp_xfrm_attrs *attrs)
 {
-	struct mlx5_core_dev *mdev = mlx5e_ipsec_sa2dev(sa_entry);
 	struct mlx5e_ipsec_addr *addrs = &attrs->addrs;
 	struct net_device *netdev = sa_entry->dev;
 	struct xfrm_state *x = sa_entry->x;
 	struct dst_entry *rt_dst_entry;
 	struct flowi4 fl4 = {};
 	struct flowi6 fl6 = {};
 	struct neighbour *n;
 	u8 addr[ETH_ALEN];
 	struct rtable *rt;
 	const void *pkey;
 	u8 *dst, *src;

 	if (attrs->mode != XFRM_MODE_TUNNEL ||
 	    attrs->type != XFRM_DEV_OFFLOAD_PACKET)
 		return;

-	mlx5_query_mac_address(mdev, addr);
+	ether_addr_copy(addr, netdev->dev_addr);
 	switch (attrs->dir) {
 	case XFRM_DEV_OFFLOAD_IN:
 		src = attrs->dmac;
 		dst = attrs->smac;

 		switch (addrs->family) {
 		case AF_INET:
 			fl4.flowi4_proto = x->sel.proto;
 			fl4.daddr = addrs->saddr.a4;
 			fl4.saddr = addrs->daddr.a4;
 			pkey = &addrs->saddr.a4;
 			break;
 		case AF_INET6:
 			fl6.flowi6_proto = x->sel.proto;
 			memcpy(fl6.daddr.s6_addr32, addrs->saddr.a6, 16);
 			memcpy(fl6.saddr.s6_addr32, addrs->daddr.a6, 16);
 			pkey = &addrs->saddr.a6;
 			break;
 		default:
 			return;
 		}
 		break;
 	case XFRM_DEV_OFFLOAD_OUT:
 		src = attrs->smac;
 		dst = attrs->dmac;
 		switch (addrs->family) {
 		case AF_INET:
 			fl4.flowi4_proto = x->sel.proto;
 			fl4.daddr = addrs->daddr.a4;
 			fl4.saddr = addrs->saddr.a4;
 			pkey = &addrs->daddr.a4;
 			break;
 		case AF_INET6:
 			fl6.flowi6_proto = x->sel.proto;
 			memcpy(fl6.daddr.s6_addr32, addrs->daddr.a6, 16);
 			memcpy(fl6.saddr.s6_addr32, addrs->saddr.a6, 16);
 			pkey = &addrs->daddr.a6;
 			break;
 		default:
 			return;
 		}
 		break;
 	default:
 		return;
 	}

 	ether_addr_copy(src, addr);

 	/* Destination can refer to a routed network, so perform FIB lookup
 	 * to resolve nexthop and get its MAC. Neighbour resolution is used as
 	 * fallback.
 	 */
 	switch (addrs->family) {
 	case AF_INET:
 		rt = ip_route_output_key(dev_net(netdev), &fl4);
 		if (IS_ERR(rt))
 			goto neigh;

 		if (rt->rt_type != RTN_UNICAST) {
 			ip_rt_put(rt);
 			goto neigh;
 		}
 		rt_dst_entry = &rt->dst;
 		break;
 	case AF_INET6:
 		if (!IS_ENABLED(CONFIG_IPV6) ||
 		    ip6_dst_lookup(dev_net(netdev), NULL, &rt_dst_entry, &fl6))
 			goto neigh;
 		break;
 	default:
 		return;
 	}

 	n = dst_neigh_lookup(rt_dst_entry, pkey);
 	if (!n) {
 		dst_release(rt_dst_entry);
 		goto neigh;
 	}

 	neigh_ha_snapshot(addr, n, netdev);
 	ether_addr_copy(dst, addr);
 	if (attrs->dir == XFRM_DEV_OFFLOAD_OUT &&
 	    is_zero_ether_addr(addr))
 		neigh_event_send(n, NULL);
 	dst_release(rt_dst_entry);
 	neigh_release(n);
 	return;

 neigh:
 	n = neigh_lookup(&arp_tbl, pkey, netdev);
 	if (!n) {
 		n = neigh_create(&arp_tbl, pkey, netdev);
 		if (IS_ERR(n))
 			return;
 		neigh_event_send(n, NULL);
 		attrs->drop = true;
 	} else {
 		neigh_ha_snapshot(addr, n, netdev);
 		ether_addr_copy(dst, addr);
 	}
 	neigh_release(n);
 }



